```csharp
[HttpGet("{driverId}/AllDocuments")]
[ProducesResponseType(typeof(IEnumerable<Document>), 200)]
[ProducesResponseType(401)]
[ProducesResponseType(500)]
[ActionName("GetAllDocuments")]
public ActionResult GetAllDocuments([FromRoute] string driverId)
{
    var driverIdRequest = new DriverIdRequest() { Id = driverId };
    var reply = _cmsAdapterClient.GetDriverDocumentsById(driverIdRequest);
    if (reply.ResultStatus == ResultStatus.Success)
    {
        var result = reply.Items
            .Where(item => !string.IsNullOrEmpty(item.DocumentUrl))
            .Select(item => new Document
            {
                ImportDate = item.ImportDate?.ToDateTimeOffset(),
                DocumentId = item.DocumentId,
                DocumentType = item.DocumentType,
                DocumentTypeCode = item.DocumentTypeCode,
                BusinessArea = item.BusinessArea,
                SequenceNumber = item.SequenceNumber,
                FaxReceivedDate = item.FaxReceivedDate?.ToDateTimeOffset(),
                UserId = item.UserId,
                BcMailSent = item.ImportDate != null && item.DocumentType != null && item.DocumentType == "Letter Out BCMail",
                CreateDate = item.CreateDate?.ToDateTimeOffset() ?? default,
                DueDate = item.DueDate?.ToDateTimeOffset(),
                Description = item.Description,
                DocumentUrl = item.DocumentUrl,
                SubmittalStatus = item.SubmittalStatus
