using Grpc.Net.Client;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Pssg.DocumentStorageAdapter.Helpers;
using Rsbc.Dmf.CaseManagement.Helpers;
using System.Net;
using System.Net.Http;

namespace Rsbc.Dmf.DriverPortal.Api
{
    /// <summary>
    /// Configuration extension helpers for the Driver Portal API.
    /// </summary>
    public static class Configuration
    {
        /// <summary>
        /// Add the Document Storage Adapter gRPC client to the service collection.
        /// When <c>DOCUMENT_STORAGE_ADAPTER_URI</c> is not configured a mock client is registered instead.
        /// </summary>
        public static void AddDocumentStorageClient(this IServiceCollection services, IConfiguration configuration)
        {
            string documentStorageAdapterURI = configuration["DOCUMENT_STORAGE_ADAPTER_URI"];

            if (string.IsNullOrEmpty(documentStorageAdapterURI))
            {
                // add the mock
                services.AddTransient(_ => DocumentStorageHelper.CreateMock(configuration));
            }
            else
            {
                var httpClientHandler = new HttpClientHandler();

                // Return `true` to allow certificates that are untrusted/invalid                    
                httpClientHandler.ServerCertificateCustomValidationCallback =
                    HttpClientHandler.DangerousAcceptAnyServerCertificateValidator;

                var httpClient = new HttpClient(httpClientHandler);
                // set default request version to HTTP 2.  Note that Dotnet Core does not currently respect this setting for all requests.
                httpClient.DefaultRequestVersion = HttpVersion.Version20;

                var initialChannel = GrpcChannel.ForAddress(documentStorageAdapterURI, new GrpcChannelOptions { HttpClient = httpClient, MaxReceiveMessageSize = null, MaxSendMessageSize = null });

                var initialClient = new Pssg.DocumentStorageAdapter.DocumentStorageAdapterClient(initialChannel);
                // call the token service to get a token.
                var tokenRequest = new Pssg.DocumentStorageAdapter.TokenRequest
                {
                    Secret = configuration["DOCUMENT_STORAGE_ADAPTER_JWT_SECRET"]
                };

                var tokenReply = initialClient.GetToken(tokenRequest);

                if (tokenReply != null && tokenReply.ResultStatus == Pssg.DocumentStorageAdapter.ResultStatus.Success)
                {
                    // Add the bearer token to the client.
                    httpClient.DefaultRequestHeaders.Add("Authorization", $"Bearer {tokenReply.Token}");

                    var channel = GrpcChannel.ForAddress(documentStorageAdapterURI, new GrpcChannelOptions { HttpClient = httpClient, MaxReceiveMessageSize = null, MaxSendMessageSize = null });

                    services.AddTransient(_ => new Pssg.DocumentStorageAdapter.DocumentStorageAdapterClient(channel));
                }
            }
        }

        /// <summary>
        /// Add the Case Management (CMS) Adapter gRPC client to the service collection.
        /// When <c>CMS_ADAPTER_URI</c> is not configured a mock client is registered instead.
        /// </summary>
        public static void AddCaseManagementAdapterClient(this IServiceCollection services, IConfiguration configuration)
        {
            string cmsAdapterURI = configuration["CMS_ADAPTER_URI"];

            if (string.IsNullOrEmpty(cmsAdapterURI))
            {
                // setup from Mock
                services.AddTransient(_ => CmsHelper.CreateMock(configuration));
            }
            else
            {
                var httpClientHandler = new HttpClientHandler();

                // Return `true` to allow certificates that are untrusted/invalid                    
                httpClientHandler.ServerCertificateCustomValidationCallback =
                    HttpClientHandler.DangerousAcceptAnyServerCertificateValidator;

                var httpClient = new HttpClient(httpClientHandler);
                // set default request version to HTTP 2.  Note that Dotnet Core does not currently respect this setting for all requests.
                httpClient.DefaultRequestVersion = HttpVersion.Version20;

                if (!string.IsNullOrEmpty(configuration["CMS_ADAPTER_JWT_SECRET"]))
                {
                    var initialChannel = GrpcChannel.ForAddress(cmsAdapterURI, new GrpcChannelOptions { HttpClient = httpClient });

                    var initialClient = new Rsbc.Dmf.CaseManagement.Service.CaseManager.CaseManagerClient(initialChannel);
                    // call the token service to get a token.
                    var tokenRequest = new Rsbc.Dmf.CaseManagement.Service.TokenRequest
                    {
                        Secret = configuration["CMS_ADAPTER_JWT_SECRET"]
                    };

                    var tokenReply = initialClient.GetToken(tokenRequest);

                    if (tokenReply != null && tokenReply.ResultStatus == Rsbc.Dmf.CaseManagement.Service.ResultStatus.Success)
                    {
                        // Add the bearer token to the client.
                        httpClient.DefaultRequestHeaders.Add("Authorization", $"Bearer {tokenReply.Token}");
                    }
                }

                var channel = GrpcChannel.ForAddress(cmsAdapterURI, new GrpcChannelOptions { HttpClient = httpClient });
                services.AddTransient(_ => new Rsbc.Dmf.CaseManagement.Service.CaseManager.CaseManagerClient(channel));
            }
        }
    }
}

