using Microsoft.AspNetCore.Http;
using Rsbc.Dmf.CaseManagement.Service;
using System.Security.Claims;
using System.Threading.Tasks;

namespace Rsbc.Dmf.DriverPortal.Api.Services
{
    public interface IUserService
    {
        Task<UserContext> GetCurrentUserContext();

        Task<bool> IsDriverAuthorized(string driverId);
    }

    public record UserContext
    {
        public string Id { get; set; }
    }

    public class UserService : IUserService
    {
        private readonly UserManager.UserManagerClient userManager;
        private readonly IHttpContextAccessor httpContext;

        public UserService(UserManager.UserManagerClient userManager, IHttpContextAccessor httpContext)
        {
            this.userManager = userManager;
            this.httpContext = httpContext;
        }

        public async Task<UserContext> GetCurrentUserContext() => new UserContext
        {
            Id = httpContext.HttpContext?.User?.FindFirstValue(ClaimTypes.Sid)
        };

        public async Task<bool> IsDriverAuthorized(string driverId)
        {
            if (string.IsNullOrEmpty(driverId)) return false;

            var request = new UserDriverAuthorizedRequest
            {
                UserId = (await GetCurrentUserContext()).Id,
                DriverId = driverId
            };

            var isAuthorizedResponse = await userManager.IsDriverAuthorizedAsync(request);

            return isAuthorizedResponse.Result;
        }
    }
}

