using Microsoft.AspNetCore.Hosting;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.TestHost;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.DependencyInjection;
using Moq;
using Rsbc.Dmf.DriverPortal.Api;
using Rsbc.Dmf.DriverPortal.Api.Model.Attribute;
using Rsbc.Dmf.DriverPortal.Api.Services;
using System;
using System.Security.Claims;
using System.Text.Json.Serialization;

namespace Rsbc.Dmf.DriverPortal.Tests
{
    public class CustomWebApplicationFactory : WebApplicationFactory<Program>
    {
        private readonly bool _isAuthorizationEnabled;

        public IConfiguration Configuration { get; protected set; }

        public CustomWebApplicationFactory(IConfiguration configuration, bool isAuthorizationEnabled = false)
        {
            Configuration = configuration;
            _isAuthorizationEnabled = isAuthorizationEnabled;
        }

        protected override void ConfigureWebHost(IWebHostBuilder builder)
        {
            builder
                .UseSolutionRelativeContentRoot("")
                .UseEnvironment("Staging")
                .UseConfiguration(Configuration)
                .ConfigureTestServices(
                    services =>
                    {
                        services.AddControllersWithViews().AddJsonOptions(x =>
                        {
                            // serialize enums as strings in api responses (e.g. Role)
                            x.JsonSerializerOptions.Converters.Add(new JsonStringEnumConverter());

                            // ignore omitted parameters on models to enable optional params (e.g. User update)
                            x.JsonSerializerOptions.DefaultIgnoreCondition = JsonIgnoreCondition.WhenWritingNull;
                        });

                        services.AddAutoMapper(AppDomain.CurrentDomain.GetAssemblies());

                        services.AddDocumentStorageClient(Configuration);
                        services.AddCaseManagementAdapterClient(Configuration);

                        // mocked HTTP context with a logged-in user
                        var mockHttpContextAccessor = new Mock<IHttpContextAccessor>();
                        var user = new ClaimsPrincipal(new ClaimsIdentity(new[]
                        {
                            new Claim(ClaimTypes.Sid, Configuration["TEST_USER_ID"] ?? "test-user-id")
                        }));
                        var httpContext = new DefaultHttpContext { User = user };
                        mockHttpContextAccessor.Setup(h => h.HttpContext).Returns(httpContext);
                        services.AddSingleton<IHttpContextAccessor>(mockHttpContextAccessor.Object);

                        services.AddTransient<AuthorizeDriverAttribute.AuthorizeDriver>();

                        if (_isAuthorizationEnabled)
                        {
                            services.AddTransient<IUserService, UserService>();
                        }
                        else
                        {
                            var mockUserService = new Mock<IUserService>();
                            mockUserService.Setup(s => s.IsDriverAuthorized(It.IsAny<string>())).ReturnsAsync(true);
                            services.AddSingleton<IUserService>(mockUserService.Object);
                        }
                    });
        }
    }
}

